QUESTIONS.lab04 = [
  { level: 'core', q: 'Why should a baseline cover at least one full business cycle?',
    options: ['So routine periodic activity, like month-end, is learned as normal', 'Because auditing tools can only export data in monthly blocks', 'So the baseline file is large enough to be cryptographically signed and stored', 'Because privacy law requires all data to be kept for one cycle'], answer: 0,
    explain: 'Short baselines miss recurring legitimate peaks and then flag them as anomalies.' },
  { level: 'core', q: 'What is a peer-group baseline?',
    options: ['Normal behaviour of users with a similar role, used as reference', 'A baseline approved by another analyst before it is deployed to production', 'The average behaviour of every account in the whole organisation', 'A baseline built only from the most senior user in each team'], answer: 0,
    explain: 'Peers in the same role give context, especially for new users without history.' },
  { level: 'core', q: 'What is baseline drift?',
    options: ['Legitimate behaviour changing over time so the old baseline is stale', 'Clock skew between log sources that shifts the timestamps slightly', 'The gradual loss of log data as storage disks start to fill up', 'An attacker slowly editing the baseline file on the SIEM server'], answer: 0,
    explain: 'Roles, tools and workloads change; baselines need rolling windows or periodic rebuilding.' },
  { level: 'core', q: 'Which signal is LEAST appropriate for a user behaviour baseline?',
    options: ['Full content of personal emails', 'Typical logon hours and days', 'Usual source devices and IPs', 'Normal data volume transferred'], answer: 0,
    explain: 'Behavioural baselines need metadata, not personal content — collecting it is unnecessary and raises privacy issues.' },
  { level: 'scenario', q: 'A baseline was trained on the same week a compromised account exfiltrated data at night. What is the risk?',
    options: ['Night-time bulk transfers may now be treated as normal for that user', 'The baseline will flag every daytime logon as anomalous from now on', 'The model will refuse to train because of the conflicting labels', 'There is no risk because baselines ignore activity outside office hours'], answer: 0,
    explain: 'Incidents inside training data become part of “normal”. Exclude or label them.' },
  { level: 'scenario', q: 'A developer moves to the finance team. Their new activity triggers many anomalies. Best action?',
    options: ['Re-baseline them against the finance peer group and their new history', 'Suppress all alerts for this user permanently to stop the noise', 'Raise the anomaly threshold for the entire organisation by fifty per cent', 'Disable their account until their old behaviour pattern returns to normal'], answer: 0,
    explain: 'Role changes are a classic cause of drift; switch peer group and rebuild the personal baseline.' },
  { level: 'scenario', q: 'User baseline: weekday logons 08:00–18:00 from one laptop. Which event deserves the closest look?',
    options: ['Saturday 03:10 logon from an unknown host', 'Tuesday 17:55 logon from the usual laptop', 'Monday 08:05 logon from the usual laptop', 'Thursday 12:30 logon from the usual laptop'], answer: 0,
    explain: 'Several deviations stack: unusual day, unusual hour and an unknown device.' },
  { level: 'scenario', q: 'A new hire has three days of history. Which comparison gives the most useful context?',
    options: ['Their activity against their role’s peer group baseline', 'Their activity against their own three-day personal baseline', 'Their activity against the CEO’s baseline as the strictest case', 'No comparison at all until 90 days of history are collected'], answer: 0,
    explain: 'Three days is too little personal history; peers provide a sensible reference and new accounts must not go unmonitored.' }
];

QUESTIONS.lab05 = [
  { level: 'core', q: 'A user’s daily downloads have mean 40 and standard deviation 8. Today they downloaded 64. What is the z-score?',
    options: ['3', '2', '8', '24'], answer: 0,
    explain: 'z = (64 − 40) / 8 = 3.' },
  { level: 'core', q: 'What does “impossible travel” detect?',
    options: ['Two logons too far apart to travel between in the time elapsed', 'A user logging on from a country listed on a sanctions register', 'A VPN connection that stays open for longer than a working day', 'A single logon that comes from an IP address with no geolocation'], answer: 0,
    explain: 'If the implied speed between two logons exceeds what is physically possible, one of them is suspicious.' },
  { level: 'core', q: 'What is a common source of false positives for impossible-travel alerts?',
    options: ['Corporate VPN or proxy egress points in other cities', 'Users who enable multi-factor authentication on phones', 'Laptops that run full-disk encryption while travelling', 'Accounts that use long passwords or passphrases to log on'], answer: 0,
    explain: 'VPNs and cloud proxies change the apparent location. Allow-list known egress IPs.' },
  { level: 'core', q: 'Lowering an anomaly threshold usually…',
    options: ['Catches more attacks but raises false positives', 'Reduces false positives and also catches more attacks', 'Has no effect once a baseline has been fully trained', 'Reduces both detections and false positives together'], answer: 0,
    explain: 'Sensitivity and false-positive rate move together — the trade-off must be tuned.' },
  { level: 'scenario', q: 'A global rule alerts above 500 downloads/day. A user who averages 40 (σ 8) downloads 210. Why was it missed?',
    options: ['The static global threshold ignores that user’s own baseline', 'The z-score of 210 is below 3, so no alert was ever expected', 'Download counts can’t be used as an anomaly detection feature', 'Anomaly detection only works for logon events, not downloads'], answer: 0,
    explain: 'For this user z ≈ 21 — extreme — but a one-size threshold built for busy servers hides it.' },
  { level: 'scenario', q: 'Logon 1: Pune 09:00. Logon 2: Frankfurt 09:40 from a known corporate VPN egress IP. Best handling?',
    options: ['Treat as likely benign VPN egress and lower or suppress severity', 'Raise a critical alert since ~6,600 km in 40 min is impossible', 'Disable the account immediately and require an identity check', 'Ignore all impossible-travel alerts for every user in future'], answer: 0,
    explain: 'Known egress points explain the jump; enrich and suppress narrowly rather than ignoring the detection everywhere.' },
  { level: 'scenario', q: 'Which combination gives the most reliable insider-risk alert?',
    options: ['Volume z-score + leaver flag from HR + new external destination', 'Volume z-score alone with the threshold set at a very low k value', 'Any download outside 09:00–17:00 regardless of user or context', 'Number of emails sent per day compared with the company average'], answer: 0,
    explain: 'Stacking several independent signals raises confidence much more than tuning one signal harder.' },
  { level: 'scenario', q: 'After lowering k from 3 to 1.5, detections rise from 1 to 2 real incidents but false positives go from 0 to 9. What should you conclude?',
    options: ['Choose k by weighing the cost of misses against analyst workload', 'Always use the lowest k because catching attacks is all that matters', 'Always use the highest k because false positives are never acceptable', 'z-scores are useless here, so remove the detector from production'], answer: 0,
    explain: 'There is no universally right k; it depends on the cost of misses versus the cost of triaging noise.' }
];

